static void otto_service(void*){for(;;){if(otto_mutex)xSemaphoreTake(otto_mutex,portMAX_DELAY);if(otto.ready){TickType_t now=xTaskGetTickCount();int buzzer_pin=pin(otto.device,"buzzer");if(buzzer_pin>=0&&otto.sound_step<5&&now>=otto.sound_at){static const uint16_t notes[8][4]={{523,659,784,1047},{392,330,262,196},{784,1047,1319,0},{659,523,659,392},{262,220,196,0},{880,0,0,0},{523,659,784,0},{110,98,82,0}};int frequency=otto.sound_step<4?notes[otto.sound_preset][otto.sound_step]:0;write_ledc(buzzer_pin,2,std::max(frequency,20),LEDC_TIMER_8_BIT,frequency?128:0);++otto.sound_step;otto.sound_at=now+pdMS_TO_TICKS(140);}int trigger=pin(otto.device,"trigger"),echo=pin(otto.device,"echo");if(trigger>=0&&echo>=0){uint64_t us=esp_timer_get_time();int level=gpio_get_level((gpio_num_t)echo);switch(otto.sonar_state){case 0:if(us-otto.sonar_at>=60000){output(trigger,0);otto.sonar_at=us;otto.sonar_state=1;}break;case 1:if(us-otto.sonar_at>=2){output(trigger,1);otto.sonar_at=us;otto.sonar_state=2;}break;case 2:if(us-otto.sonar_at>=10){output(trigger,0);otto.sonar_at=us;otto.sonar_state=3;}break;case 3:if(level){otto.echo_started=us;otto.sonar_state=4;}else if(us-otto.sonar_at>30000){otto.distance=0;otto.sonar_at=us;otto.sonar_state=0;}break;case 4:if(!level){otto.distance=std::min<int>((us-otto.echo_started)/58,500);otto.sonar_at=us;otto.sonar_state=0;}else if(us-otto.echo_started>30000){otto.distance=0;otto.sonar_at=us;otto.sonar_state=0;}break;}}}if(otto_mutex)xSemaphoreGive(otto_mutex);vTaskDelay(pdMS_TO_TICKS(1));}}
