  if (!strcmp(type,"HELLO")) { cJSON *out=cJSON_CreateObject(); cJSON_AddStringToObject(out,"type","HELLO"); cJSON_AddStringToObject(out,"protocol","CapiLink"); cJSON_AddStringToObject(out,"firmware",CAPI_FIRMWARE_VERSION); cJSON_AddNumberToObject(out,"abi",ABI); cJSON_AddStringToObject(out,"board",CAPI_BOARD_ID); cJSON_AddNumberToObject(out,"maxRulesBytes",MAX_RULES); cJSON *caps=cJSON_AddArrayToObject(out,"capabilities"); for(const char *cap:{"core","parallel","expressions","variables","timers","component-state","gpio","led","traffic","motor","robot","otto","servo","buzzer","matrix","display","display-lcd","display-lcd1602","display-lcd2004","display-lcd1602keypad","display-graphic","display-ssd1306","display-ili9341","display-ili9488","display-keypad","visual-wait","messages","wifi","wifi-messages","counter","serial","digital-input","analog-input"}) cJSON_AddItemToArray(caps,cJSON_CreateString(cap)); cJSON *resources=cJSON_AddObjectToObject(out,"resources");cJSON_AddNumberToObject(resources,"pwmChannels",8); send_json(out); }
